using System.IO;
using System.Diagnostics;
using System.Text.Json;
using System.Windows;
using Microsoft.Win32;
using Microsoft.Web.WebView2.Core;
namespace GymOS.Windows;
public partial class MainWindow:Window {
 readonly string Site;readonly string SettingsPath;string DatabasePath;string? Pending;string LastStatus="";readonly NativeSpeech Speech=new();
 public MainWindow(){InitializeComponent();var config=Path.Combine(AppContext.BaseDirectory,"gymos.json");var url=File.Exists(config)?JsonDocument.Parse(File.ReadAllText(config)).RootElement.GetProperty("siteUrl").GetString():"https://gymos-enterprise.vercel.app";if(!Uri.TryCreate(url,UriKind.Absolute,out var uri)||uri.Scheme!="https"||!string.IsNullOrEmpty(uri.UserInfo)||uri.AbsolutePath!="/")throw new InvalidOperationException("Set an HTTPS deployment origin in gymos.json.");if(uri.Host=="gym-os-liart.vercel.app"||uri.Host=="gymos-web-pulse.bouncybowl4.chatgpt.site")uri=new Uri("https://gymos-enterprise.vercel.app");Site=uri.GetLeftPart(UriPartial.Authority);var root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"GymOS");Directory.CreateDirectory(root);SettingsPath=Path.Combine(root,"desktop-settings.json");DatabasePath=Path.Combine(root,"Backups","gymos-backups.sqlite");if(File.Exists(SettingsPath)){try{DatabasePath=JsonDocument.Parse(File.ReadAllText(SettingsPath)).RootElement.GetProperty("backupDatabase").GetString()??DatabasePath;}catch{}}Report("Server: "+Site+" · "+DatabasePath);}
 void Report(string text){LastStatus=text;var core=Browser?.CoreWebView2;if(core!=null&&Uri.TryCreate(Browser?.Source?.AbsoluteUri,UriKind.Absolute,out var uri)&&uri.GetLeftPart(UriPartial.Authority)==Site)core.PostWebMessageAsJson(JsonSerializer.Serialize(new{type="gymos-desktop-status",status=text,path=DatabasePath,site=Site,version="1.1.1"}));}
 void ChooseDatabase(object sender,RoutedEventArgs e){var dialog=new SaveFileDialog{Title="اختيار ملف قاعدة النسخ الاحتياطية / Choose backup database",Filter="SQLite database|*.sqlite",FileName="gymos-backups.sqlite",OverwritePrompt=false};if(dialog.ShowDialog()!=true)return;try{BackupStore.Initialize(dialog.FileName);DatabasePath=dialog.FileName;File.WriteAllText(SettingsPath,JsonSerializer.Serialize(new{backupDatabase=DatabasePath}));Report(DatabasePath);}catch(Exception ex){MessageBox.Show(ex.Message,"GYM OS backup");}}
 void SaveBackup(object sender,RoutedEventArgs e)=>RequestBackup("save");void ExportBackup(object sender,RoutedEventArgs e)=>RequestBackup("export");
 async void RequestBackup(string action){if(Browser.CoreWebView2==null||Pending!=null)return;if(!Uri.TryCreate(Browser.Source?.AbsoluteUri,UriKind.Absolute,out var uri)||uri.GetLeftPart(UriPartial.Authority)!=Site)return;Pending=action;Report("جارٍ التحقق من حساب المالك… / Checking owner account…");try{await Browser.CoreWebView2.ExecuteScriptAsync("(async()=>{try{const r=await fetch('/api/backup',{cache:'no-store',signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('Sign in as owner / سجل دخول المالك');const data=await r.json();window.chrome.webview.postMessage({type:'gymos-backup',backup:data});}catch(e){window.chrome.webview.postMessage({type:'gymos-backup-error',message:String(e)});}})()");}catch{Pending=null;Report("تعذر طلب النسخة / Backup request failed");}}
 async Task SpeakNative(string id,string text,string voice,double rate){var origin=Browser.Source?.AbsoluteUri;bool ok;try{await Speech.Speak(text,voice,rate);ok=true;}catch{ok=false;}try{if(Browser.CoreWebView2!=null&&Browser.Source?.AbsoluteUri==origin)Browser.CoreWebView2.PostWebMessageAsJson(JsonSerializer.Serialize(new{type="gymos-speech-result",id,ok}));}catch{/* window closed or navigated during playback */}}
 void ReceiveBackup(object? sender,CoreWebView2WebMessageReceivedEventArgs args){if(args.WebMessageAsJson.Length>30000000)return;if(!Uri.TryCreate(args.Source,UriKind.Absolute,out var uri)||uri.GetLeftPart(UriPartial.Authority)!=Site)return;try{using var command=JsonDocument.Parse(args.WebMessageAsJson);var message=command.RootElement;if(message.TryGetProperty("type",out var kind)&&kind.GetString()=="gymos-desktop"){if(args.WebMessageAsJson.Length>12000||!message.TryGetProperty("action",out var requested)||requested.ValueKind!=JsonValueKind.String)return;var name=requested.GetString();if(!DesktopCommands.Allowed(name))return;switch(name){case "speechVoices":Browser.CoreWebView2.PostWebMessageAsJson(JsonSerializer.Serialize(new{type="gymos-speech-voices",voices=Speech.Voices()}));break;case "speak":if(message.TryGetProperty("text",out var speechText)&&speechText.ValueKind==JsonValueKind.String&&message.TryGetProperty("voice",out var speechVoice)&&speechVoice.ValueKind==JsonValueKind.String&&message.TryGetProperty("rate",out var speechRate)&&speechRate.TryGetDouble(out var rate))_ = SpeakNative(message.TryGetProperty("id",out var requestId)&&requestId.ValueKind==JsonValueKind.String?(requestId.GetString()??"")[..Math.Min(100,requestId.GetString()!.Length)]:"",speechText.GetString()!,speechVoice.GetString()!,rate);break;case "stopSpeech":Speech.Stop();break;case "status":Report(LastStatus);break;case "chooseDatabase":ChooseDatabase(this,new RoutedEventArgs());break;case "save":RequestBackup("save");break;case "export":RequestBackup("export");break;case "refreshSignIn":RefreshSignIn(this,new RoutedEventArgs());break;case "speechSettings":Process.Start(new ProcessStartInfo("ms-settings:speech"){UseShellExecute=true});break;}return;}}catch{return;}if(Pending==null)return;var action=Pending;Pending=null;try{if(args.WebMessageAsJson.Length>30000000)throw new InvalidOperationException("Backup too large");using var json=JsonDocument.Parse(args.WebMessageAsJson);var root=json.RootElement;if(root.GetProperty("type").GetString()!="gymos-backup")throw new InvalidOperationException("Sign in as the gym owner / سجل دخول مالك النادي");var backup=root.GetProperty("backup");if(backup.GetProperty("format").GetString()!="gymos-backup"||backup.GetProperty("version").GetInt32()!=2)throw new InvalidOperationException("Invalid backup format");var tenant=backup.GetProperty("tenant").GetString()!;if(string.IsNullOrWhiteSpace(tenant))throw new InvalidOperationException("Missing tenant");if(action=="save"){BackupStore.Save(DatabasePath,tenant,backup.GetRawText());Report("تم حفظ نسخة مشفرة / Encrypted backup saved · "+DateTime.Now.ToString("yyyy-MM-dd HH:mm")+" · "+DatabasePath);}else{var payload=BackupStore.Latest(DatabasePath,tenant);var save=new SaveFileDialog{Title="تصدير JSON للاستعادة من شاشة تشغيل النادي / Export backup",Filter="GYM OS JSON|*.json",FileName="gymos-backup-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".json"};if(save.ShowDialog()==true){File.WriteAllText(save.FileName,payload);Report("تم التصدير. ملف JSON غير مشفر / Exported JSON is not encrypted");}}}catch(Exception ex){Report("تعذر النسخ / Backup failed: "+ex.Message);}}
 async void RefreshSignIn(object sender,RoutedEventArgs e){if(Browser.CoreWebView2==null)return;try{var core=Browser.CoreWebView2;var cookies=await core.CookieManager.GetCookiesAsync(Site);foreach(var cookie in cookies)if(cookie.Name.StartsWith("sb-",StringComparison.Ordinal))core.CookieManager.DeleteCookie(cookie);await core.CallDevToolsProtocolMethodAsync("Network.clearBrowserCache","{}");core.Navigate(Site+"/sign-in");Report("Server: "+Site+" · أدخل بيانات الدخول من جديد / Sign in again");}catch{Report("تعذر تجديد الجلسة / Could not refresh sign-in");}}
 async void Start(object sender,RoutedEventArgs e){try{
  var profile=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"GymOS","WebProfile");var environment=await CoreWebView2Environment.CreateAsync(null,profile);await Browser.EnsureCoreWebView2Async(environment);var core=Browser.CoreWebView2;core.Settings.AreDevToolsEnabled=false;core.Settings.IsStatusBarEnabled=false;core.Settings.AreHostObjectsAllowed=false;core.WebMessageReceived+=ReceiveBackup;
  core.NavigationStarting+=(_,args)=>{Pending=null;Speech.Stop();if(!Uri.TryCreate(args.Uri,UriKind.Absolute,out var uri)||uri.Scheme!="https"){args.Cancel=true;return;}if(uri.GetLeftPart(UriPartial.Authority)!=Site){args.Cancel=true;Process.Start(new ProcessStartInfo(uri.AbsoluteUri){UseShellExecute=true});}};
  core.NewWindowRequested+=(_,args)=>{args.Handled=true;if(Uri.TryCreate(args.Uri,UriKind.Absolute,out var uri)&&uri.Scheme=="https"){if(uri.GetLeftPart(UriPartial.Authority)==Site)core.Navigate(uri.AbsoluteUri);else Process.Start(new ProcessStartInfo(uri.AbsoluteUri){UseShellExecute=true});}};
  core.PermissionRequested+=(_,args)=>{if(args.PermissionKind==CoreWebView2PermissionKind.Camera&&Uri.TryCreate(args.Uri,UriKind.Absolute,out var uri)&&uri.GetLeftPart(UriPartial.Authority)==Site){args.State=MessageBox.Show("السماح للكاميرا لتصوير العضو أو قراءة الكارت؟\nAllow camera for member photo / card scanning?","GYM OS",MessageBoxButton.YesNo,MessageBoxImage.Question)==MessageBoxResult.Yes?CoreWebView2PermissionState.Allow:CoreWebView2PermissionState.Deny;}else args.State=CoreWebView2PermissionState.Deny;};
  core.NavigationCompleted+=(_,args)=>{Status.Visibility=args.IsSuccess?Visibility.Collapsed:Visibility.Visible;Status.Text=args.IsSuccess?"":"تعذر الاتصال. تحقق من الإنترنت.\nConnection unavailable. Check internet.";};Closing+=(_,_)=>Speech.Dispose();core.Navigate(Site);
 }catch(Exception ex){Status.Text="يلزم Microsoft Edge WebView2 Runtime.\nInstall Microsoft Edge WebView2 Runtime.\n"+ex.Message;}}
}
